-- A withdrawn correction never resurrects an older asset release.
CREATE OR REPLACE FUNCTION can_read_learning_asset(s TEXT,r UUID,u TEXT) RETURNS BOOLEAN AS $$
 SELECT EXISTS(SELECT 1 FROM "LearningAssetRelease" release JOIN "LearningAssetRights" rights ON rights."schoolId"=release."schoolId" AND rights."id"=release."rightsId" JOIN "PrivateLearningAsset" a ON a."schoolId"=release."schoolId" AND a."id"=release."assetId" AND a."id"=rights."assetId" WHERE release."schoolId"=s AND release."id"=r AND phase10_owner(s,release."actorUserId") AND phase10_owner(s,rights."actorUserId") AND rights."actorUserId"<>a."proposerUserId" AND (rights."expiresAt" IS NULL OR rights."expiresAt">clock_timestamp()) AND can_read_library_catalog(s,rights."catalogReleaseId",u) AND EXISTS(SELECT 1 FROM "LearningAssetInspection" i WHERE i."schoolId"=s AND i."assetId"=a."id" AND i."verdict"='CLEAN') AND NOT EXISTS(SELECT 1 FROM "LearningAssetRelease" newer JOIN "LearningAssetRights" nr ON nr."schoolId"=newer."schoolId" AND nr."id"=newer."rightsId" WHERE newer."schoolId"=s AND nr."catalogReleaseId"=rights."catalogReleaseId" AND (newer."createdAt",newer."id")>(release."createdAt",release."id")) AND NOT EXISTS(SELECT 1 FROM "LearningAssetWithdrawal" w WHERE w."schoolId"=s AND w."releaseId"=r));
$$ LANGUAGE sql STABLE;
CREATE INDEX "LearningAssetRights_catalog_context" ON "LearningAssetRights"("schoolId","catalogReleaseId","id");
CREATE INDEX "LearningAssetRelease_current" ON "LearningAssetRelease"("schoolId","rightsId","createdAt" DESC,"id" DESC);
